// MachineAdminServiceClient is a client for the aide.machine.v1.MachineAdminService service.
type MachineAdminServiceClient interface {
	// Rooms (ROOMS-DESIGN-2026-11-22, G2-a): the owner and bots talking, kept
	// and run by this machine, the room's host. A direct room is the owner and
	// one personal agent: its conversation. Owner only.
	ListRooms(context.Context, *v1.ListRoomsRequest) (*v1.ListRoomsResponse, error)
	// The direct room with a personal agent, made the first time.
	OpenDirectRoom(context.Context, *v1.OpenDirectRoomRequest) (*v1.Room, error)
	ListRoomMessages(context.Context, *v1.ListRoomMessagesRequest) (*v1.ListRoomMessagesResponse, error)
	// The owner says something in the room; the members it is for are woken.
	// Sent again with the same idempotency key, it is not said twice.
	PostRoomMessage(context.Context, *v1.PostRoomMessageRequest) (*v1.RoomMessage, error)
	// A room of several bots (G2-b): the personal agents and this machine's
	// coding agents the owner picked, each coding agent in a project of its
	// own here.
	CreateRoom(context.Context, *v1.CreateRoomRequest) (*v1.Room, error)
	// Its name, how it is run, its round limit.
	UpdateRoom(context.Context, *v1.UpdateRoomRequest) (*v1.Room, error)
	// Stops a round table: nobody more is woken, coding agents at work are
	// interrupted, answers that come after are kept but hand nothing on.
	StopRoom(context.Context, *v1.StopRoomRequest) (*v1.Room, error)
	// The owner read the room up to now.
	MarkRoomSeen(context.Context, *v1.MarkRoomSeenRequest) (*v1.Room, error)
	DeleteRoom(context.Context, *v1.DeleteRoomRequest) (*v1.DeleteRoomResponse, error)
	// Whether the members picked for a room can be reached now (工单 #159),
	// asked for real, not read from the roster: a personal agent's grant
	// here, its inbox at the post office and whether anything takes its
	// letters now; a coding agent of this machine's, checked again now. The
	// owner's device asks each coding agent's own machine of it, and the
	// room's host of the personal agents.
	CheckRoomMembers(context.Context, *v1.CheckRoomMembersRequest) (*v1.CheckRoomMembersResponse, error)
	ApplyAdminCommand(context.Context, *v1.ApplyAdminCommandRequest) (*v1.ApplyAdminCommandResponse, error)
	PushRevocations(context.Context, *v1.PushRevocationsRequest) (*v1.PushRevocationsResponse, error)
	// The git repositories under the home folder, for Add a Project: read
	// when the person opens it, never kept (docs/onboarding.md §5.5).
	ListRepos(context.Context, *v1.ListReposRequest) (*v1.ListReposResponse, error)
	// The folders in one folder, for Add a Project's folder browser: read
	// when the person opens it, never kept.
	ListFolders(context.Context, *v1.ListFoldersRequest) (*v1.ListFoldersResponse, error)
	// One short fixed turn of a coding agent in a scratch folder, to prove it
	// is installed and signed in: no session, project or grant is involved.
	// Signs a coding agent's command line in on this machine (Claude Code:
	// `claude auth login`), started here in the background: the browser
	// opens on this machine and the owner signs in there. Aide never sees
	// the account, the password or the token (工单 #51). Again while one is
	// under way: its state; cancel stops it.
	StartAgentLogin(context.Context, *v1.StartAgentLoginRequest) (*v1.StartAgentLoginResponse, error)
	TestAgent(context.Context, *v1.TestAgentRequest) (*v1.TestAgentResponse, error)
	// The machine's ops log (MachineOpsService), newest first.
	ListExecLog(context.Context, *v1.ListExecLogRequest) (*v1.ListExecLogResponse, error)
	// The sessions DeepSeek Harness (DSH) keeps on this machine that Aide
	// did not start (the owner's own in DSH Desktop, another tool's), newest
	// activity first: read from DSH's files, which nothing here writes, and
	// without taking a session's lock. Not its subagents' sessions.
	ListDSHSessions(context.Context, *v1.ListDSHSessionsRequest) (*v1.ListDSHSessionsResponse, error)
	// One DSH session and a page of its conversation as DSH saved it, as
	// session events (as SessionService.ListEvents pages them). Read only.
	ReadDSHSession(context.Context, *v1.ReadDSHSessionRequest) (*v1.ReadDSHSessionResponse, error)
	// The Claude Code sessions the Claude desktop app lists on this machine
	// (its own index), that Aide did not start, newest activity first: read
	// from the app's and Claude Code's files, which nothing here writes.
	// Owner only.
	// The models (with their reasoning efforts) and permission presets DSH
	// offers a taken-over session, and the ones it has now, through the
	// bridge plugin: what SendDSHMessage may set.
	DSHSessionOptions(context.Context, *v1.DSHSessionOptionsRequest) (*v1.DSHSessionOptionsResponse, error)
	ListClaudeSessions(context.Context, *v1.ListClaudeSessionsRequest) (*v1.ListClaudeSessionsResponse, error)
	// One of them and a page of its conversation, from Claude Code's
	// transcript, as session events. Read only. Owner only.
	ReadClaudeSession(context.Context, *v1.ReadClaudeSessionRequest) (*v1.ReadClaudeSessionResponse, error)
	// Goes on with one of them in Aide (工单 #181): a session of Aide's that
	// resumes it — Claude Code's own id, in its own folder — with the
	// owner's message as its next turn, so what follows is in its transcript
	// as Claude wrote it before. One already gone on with is that session.
	// Owner only.
	ContinueClaudeSession(context.Context, *v1.ContinueClaudeSessionRequest) (*v1.ContinueClaudeSessionResponse, error)
	// Messages held for the owner before they reach a session
	// (docs/agent-messages.md §15.5): from an agent let in less than 7 days
	// ago, in a chain at hop 3 or more, or matching the owner's information
	// boundary for the session's agent. Kept on this machine, not at the
	// post office; one not released within a day expires. Owner only.
	ListHeldMessages(context.Context, *v1.ListHeldMessagesRequest) (*v1.ListHeldMessagesResponse, error)
	// Releases one to its session (it goes on as if never held), or discards
	// it (refused; its sender is told). Only messages, never an action: a
	// release is recorded in the audit log.
	ReleaseHeldMessage(context.Context, *v1.ReleaseHeldMessageRequest) (*v1.ReleaseHeldMessageResponse, error)
	// Taking over a DSH session (docs/dsh-takeover.md): the owner turns it
	// on for one session (off for every session until then), then sends it
	// messages and stops its turn through the Aide bridge plugin in DSH
	// Desktop, which hands them to the DSH Host that owns the session: a
	// message sent while a turn runs waits for the next turn there, as one
	// typed in DSH would. Owner only. Turning it off changes nothing in DSH.
	SetDSHTakeover(context.Context, *v1.SetDSHTakeoverRequest) (*v1.SetDSHTakeoverResponse, error)
	// Sends the owner's message into a taken-over DSH session.
	// FAILED_PRECONDITION, with what to do, when takeover is off, the bridge
	// is not running (DSH Desktop closed, or the plugin not installed or
	// off), or another DSH process holds the session; DEADLINE_EXCEEDED
	// when DSH did not take it in time. Nothing is sent then.
	SendDSHMessage(context.Context, *v1.SendDSHMessageRequest) (*v1.SendDSHMessageResponse, error)
	// Stops the current turn of a taken-over DSH session that runs in DSH
	// Desktop.
	InterruptDSHSession(context.Context, *v1.InterruptDSHSessionRequest) (*v1.InterruptDSHSessionResponse, error)
	// Prepares installing the bridge plugin, which DSH Desktop's own plugin
	// manager then does (Plugins page): backs up DSH's configuration files
	// and writes the plugin's package into the DSH home. Changes nothing DSH
	// reads. Owner only.
	PrepareDSHBridge(context.Context, *v1.PrepareDSHBridgeRequest) (*v1.PrepareDSHBridgeResponse, error)
	// Installs the bridge plugin by handing it to DSH (工单 #59): prepares the
	// package as PrepareDSHBridge does, then starts a DSH session in the
	// plugin's folder whose task is to install it in DSH Desktop's profile,
	// find and clear what stops it (a file a running program holds, a broken
	// package left by an earlier failure), restart DSH Desktop, check the
	// plugin answers, and report with `aided dsh-bridge report`. How it goes
	// is DSHBridge.install. Owner only.
	InstallDSHBridge(context.Context, *v1.InstallDSHBridgeRequest) (*v1.InstallDSHBridgeResponse, error)
	// The coding agents the owner added on this machine (custom agents):
	// ACP agents started with the command given, listed and run as the
	// built-in ones are. Kept in the machine's agents.json; the values of
	// secret variables are in its credential store and never sent back.
	ListCustomAgents(context.Context, *v1.ListCustomAgentsRequest) (*v1.ListCustomAgentsResponse, error)
	// Adds a custom agent, or changes the one by that name; in use at once.
	SaveCustomAgent(context.Context, *v1.SaveCustomAgentRequest) (*v1.SaveCustomAgentResponse, error)
	RemoveCustomAgent(context.Context, *v1.RemoveCustomAgentRequest) (*v1.RemoveCustomAgentResponse, error)
	// Starts an agent as given (saved or not) once, in a scratch folder, and
	// does the ACP handshake: initialize, then a new session; then stops it.
	TestCustomAgent(context.Context, *v1.TestCustomAgentRequest) (*v1.TestCustomAgentResponse, error)
	// Lists installable agents from the official ACP Registry (with local cache
	// and bundled snapshot fallback), annotated for this machine's OS/arch and
	// current installation status (工单 #110).
	ListACPRegistry(context.Context, *v1.ListACPRegistryRequest) (*v1.ListACPRegistryResponse, error)
	// Downloads (with SHA-256 verification for binary archives), installs in a
	// machine-isolated directory, and registers an official ACP Registry agent
	// as a custom ACP agent on this machine (工单 #110).
	InstallACPRegistryAgent(context.Context, *v1.InstallACPRegistryAgentRequest) (*v1.InstallACPRegistryAgentResponse, error)
	// Runs a built-in agent's CLI's own updater (工单 #178), its output passed
	// through unchanged, then checks the agent again: never Aide replacing
	// the program itself.
	UpdateAgent(context.Context, *v1.UpdateAgentRequest) (*v1.UpdateAgentResponse, error)
}

